CREATE TABLE IF NOT EXISTS "MobileNotices"
(
    "Id"             integer GENERATED BY DEFAULT AS IDENTITY,
    "Title"          character varying(200)      NOT NULL,
    "Message"        character varying(2000),
    "Url"            character varying(500),
    "IsPublished"    boolean                     NOT NULL DEFAULT false,
    "PublishedFrom"  timestamp without time zone,
    "PublishedTo"    timestamp without time zone,
    "DisplayOrder"   integer                     NOT NULL DEFAULT 0,
    "CreatedBy"      text,
    "CreatedAt"      timestamp without time zone NOT NULL,
    "EditedBy"       text,
    "EditedAt"       timestamp without time zone NOT NULL,
    "MACAddress"     text,
    CONSTRAINT "PK_MobileNotices" PRIMARY KEY ("Id")
);

CREATE INDEX IF NOT EXISTS "IX_MobileNotices_Published"
    ON "MobileNotices" ("IsPublished", "DisplayOrder", "CreatedAt");

CREATE TABLE IF NOT EXISTS "MobileSliders"
(
    "Id"             integer GENERATED BY DEFAULT AS IDENTITY,
    "Title"          character varying(200)      NOT NULL,
    "Subtitle"       character varying(300),
    "ImagePath"      character varying(500),
    "TargetUrl"      character varying(500),
    "IsPublished"    boolean                     NOT NULL DEFAULT false,
    "PublishedFrom"  timestamp without time zone,
    "PublishedTo"    timestamp without time zone,
    "DisplayOrder"   integer                     NOT NULL DEFAULT 0,
    "CreatedBy"      text,
    "CreatedAt"      timestamp without time zone NOT NULL,
    "EditedBy"       text,
    "EditedAt"       timestamp without time zone NOT NULL,
    "MACAddress"     text,
    CONSTRAINT "PK_MobileSliders" PRIMARY KEY ("Id")
);

CREATE INDEX IF NOT EXISTS "IX_MobileSliders_Published"
    ON "MobileSliders" ("IsPublished", "DisplayOrder", "CreatedAt");
